"""Genera un dashboard autónomo e informe, sin servicios externos."""
from pathlib import Path
import base64,json,zipfile
from calibracion import generar_calibracion
from analizar import BASE,ROOT

def main():
 d=BASE/'dashboard';out=ROOT/'03_resultados'/'escenario_base';a=json.loads((out/'auditoria.json').read_text(encoding='utf-8'));s=json.loads((out/'sensibilidad_resumen.json').read_text(encoding='utf-8'));t=a['totales']

 payload_path=d/'datos.js';payload=json.loads(payload_path.read_text(encoding='utf-8').split('=',1)[1].rstrip(';'))
 payload['trazabilidad']={'archivos':[{'archivo':Path(f['ruta']).name,'sha256':f['sha256'],'bytes':f['bytes']} for f in a['archivos']],'versiones':a['versiones']}
 payload_path.write_text('window.GAIA_DATA='+json.dumps(payload,ensure_ascii=False,allow_nan=False,separators=(',',':'))+';',encoding='utf-8')
 generar_calibracion(out,d)
 html=(d/'index.html').read_text(encoding='utf-8-sig')
 for name in ['datos.js','sensibilidad.js','calibracion_datos.js','app.js','calibracion.js']:
  js=(d/name).read_text(encoding='utf-8-sig').replace('</script','<\\/script');html=html.replace('<script src="'+name+'"></script>','<script>'+js+'</script>')
 font=base64.b64encode((d/'assets'/'InterVariable.woff2').read_bytes()).decode();html=html.replace("url('assets/InterVariable.woff2')", "url('data:font/woff2;base64,"+font+"')")
 logo=base64.b64encode((d/'assets'/'grupo-bid-blanco.svg').read_bytes()).decode();html=html.replace('src="assets/grupo-bid-blanco.svg"','src="data:image/svg+xml;base64,'+logo+'"')
 (ROOT/'index.html').write_text(html,encoding='utf-8')
 def num(v):return f'{v:,.0f}'.replace(',','.')
 def pct(v,d):return f'{100*v/d:.2f}'.replace('.',',')+'%'
 groups=['total','pobre','no_pobre']; labels={'total':'Total','pobre':'Pobre','no_pobre':'No pobre'}
 lines=['# Población expuesta a amenazas RP100 — El Salvador','','Fecha: 21 de octubre de 2026. Escenario base con los umbrales operativos documentados.','','## Resultado principal','',f'De {num(t["base_total"])} habitantes modelados por WorldPop 2025, **{num(t["union_total"])} ({pct(t["union_total"],t["base_total"])})** se localizan en áreas expuestas a una o más amenazas. La unión cuenta cada habitante una sola vez.', '', f'Para dos o más amenazas, el resultado es **{num(sum(t[f"numero_{k}_total"] for k in [2,3,4]))} habitantes ({pct(sum(t[f"numero_{k}_total"] for k in [2,3,4]),t["base_total"])})**. Ambas definiciones se mantienen separadas.','','| Escenario | Total expuesta | Pobre expuesta | No pobre expuesta | % de población total |','|---|---:|---:|---:|---:|']
 names={'inundacion':'Inundación ≥0,1 m','sismo':'PGA ≥0,10 g','viento':'Viento huracanado ≥20 m/s','calor':'WBGT ≥30 °C','union':'Una o más amenazas',**{f'numero_{k}':f'Exactamente {k} amenazas' for k in range(5)}}
 for k,label in names.items():lines.append('| '+label+' | '+' | '.join(num(t[f'{k}_{g}']) for g in groups)+' | '+pct(t[k+'_total'],t['base_total'])+' |')
 lines+=['','## Comparación por grupo poblacional','','| Grupo | Población base | Una o más amenazas | % del propio grupo | Dos o más amenazas | % del propio grupo |','|---|---:|---:|---:|---:|---:|']
 for g in groups:
  multi=sum(t[f'numero_{k}_{g}'] for k in [2,3,4]);lines.append(f'| {labels[g]} | {num(t["base_"+g])} | {num(t["union_"+g])} | {pct(t["union_"+g],t["base_"+g])} | {num(multi)} | {pct(multi,t["base_"+g])} |')
 lines+=['','## Lectura del resultado','',f'El mapa sísmico tiene un mínimo válido de 0,20139 g, superior al umbral base 0,10 g. Por eso el sismo por sí solo comprende {pct(t["sismo_total"],t["base_total"])} de la población. Esta característica de los datos y el criterio de exposición explica buena parte de la unión cercana a 100%; no equivale a que toda esa población sufrirá daños.', '', 'Los porcentajes representan exposición potencial a los mapas suministrados. No son probabilidades individuales de daño ni un evento multiamenaza conjunto RP100. Los totales son estimaciones modeladas; las tablas se redondean solo para presentación.','','## Sensibilidad documentada','',f'Se evaluaron las {s["combinaciones"]} combinaciones de profundidad 0,1/0,2/0,3 m; PGA 0,1/0,2/0,3 g; viento 20/25/33 m/s; y WBGT ≥28/≥30/≥32 °C. Se evalúan todas las combinaciones de los niveles documentados, sin seleccionar escenarios por el porcentaje obtenido.', '',f'Una o más amenazas: **{s["min_pct_una_o_mas"]:.2f}%–{s["max_pct_una_o_mas"]:.2f}%**. Dos o más amenazas: **{s["min_pct_dos_o_mas"]:.2f}%–{s["max_pct_dos_o_mas"]:.2f}%**. El extremo superior de una o más amenazas es 99,9954%, aunque al redondear a dos decimales aparezca 100,00%.','',s['nota'],'','## Reglas aplicadas','','- Soporte: centros de las celdas WorldPop positivas, no hexágonos agregados. Muestreo de la celda contenedora en cada grilla nativa; es una aproximación puntual que no reparte por área las celdas fronterizas.','- Se conserva la suma nacional de WorldPop. Los centros fuera de límites se asignan al municipio más cercano en UTM 16N, con desempate determinista.','- RWI del punto más cercano, con distancia y error original conservados en el detalle. Ranking ponderado por población y fracción común para los empates en el corte de pobreza.','- Las tasas municipales originales se aceptan para población 2025. Las faltantes se imputan por promedio simple de vecinos con tasa original y segmento de límite compartido. No se promedian otras imputaciones.','- NoData o ausencia de cobertura de una amenaza implica cero exposición a esa amenaza, como criterio operativo del análisis; los indicadores de dato válido se conservan. No significa una comprobación independiente de ausencia de peligro.','- Se usan los 266 polígonos de la fuente territorial, incluidos cuatro cuerpos de agua sin población asignada. No se actualiza la división administrativa.','','## Tasas imputadas','','| Unidad | Tasa imputada | Vecinos con tasa original |','|---|---:|---|']
 imputed=json.loads((out/'tasas_imputadas.json').read_text(encoding='utf-8'))
 for r in imputed:lines.append(f'| {r["municipio"]} ({r["codigo"]}) | {r["tasa"]:.4f}% | '+', '.join(v['ADM2_EN'] for v in r['vecinos'])+' |')
 lines+=['','## Cobertura y controles','',f'Asignación al municipio más cercano: {num(a["asignacion_limites"]["poblacion"])} habitantes en {num(a["asignacion_limites"]["celdas"])} celdas. Distancia máxima: {a["asignacion_limites"]["distancia_max_m"]:.1f} m.','','Población sobre ausencia de dato válido de amenaza (tratada como cero exposición):']
 for k,v in a['parametros'].items():lines.append(f'- {names[k]}: {num(v["poblacion_sin_dato"])} habitantes; de ellos {num(v["poblacion_fuera_extension"])} fuera de la extensión del archivo.')
 lines+=['','Todos los balances pasaron con errores menores a 0,00001 personas: calibración municipal, pobre + no pobre = total, categorías 0–4 = población y categorías 1–4 = unión. Seis pruebas unitarias verificaron empates, ponderación poblacional, tasas extremas, operadores y conteo de la unión.','','## Limitaciones','','La resolución de WBGT es aproximadamente 27 km, de viento 2 km y de población/inundación unos 100 m. No deben interpretarse las diferencias municipales o el RWI asignado a 100 m como observaciones a esa escala. La capa WBGT registra un tratamiento previo por vecino válido cercano. Las fechas y definiciones originales de las amenazas proceden de los archivos y de las definiciones adoptadas para este ejercicio, sin validación independiente del modelo.','','## Archivos entregados','','- `index.html`: dashboard autónomo, funciona sin internet.','- `03_resultados/escenario_base/indicadores.csv`: resultados nacionales y por unidad, por amenaza, unión y 0–4 amenazas.','- `03_resultados/escenario_base/municipios.csv`: atributos completos por unidad.','- `03_resultados/escenario_base/sensibilidad.csv`: las 81 combinaciones completas.','- `03_resultados/escenario_base/resultados_municipales.gpkg`: resultados espaciales.','- `03_resultados/escenario_base/poblacion_y_exposicion.tif`: población total/pobre/no pobre, número de amenazas y combinación en bits.','- `03_resultados/escenario_base/celdas.csv.gz`: detalle por celda con RWI, distancias, grupo poblacional, exposición y cobertura.','- `03_resultados/escenario_base/auditoria.json`: parámetros, reglas, versiones, verificaciones y hashes de insumos.','- `03_resultados/escenario_base/tasas_imputadas.json` y `asignaciones_fuera_limites.csv`: trazabilidad de decisiones espaciales.','','## Diseño','','El dashboard utiliza la identidad visual del Grupo BID: logo oficial vectorial en español, fuente Inter incluida localmente con licencia SIL Open Font License, diseño editorial petróleo/cian , con superficies claras y escala secuencial petróleo/cian. Los mapas mostrados se simplifican solo para visualización; los cálculos usan las geometrías originales.']
 (ROOT/'05_documentacion'/'Informe_resultados.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')

 (ROOT/'04_dashboard').mkdir(exist_ok=True)
 with zipfile.ZipFile(ROOT/'04_dashboard'/'Dashboard_para_publicar.zip','w',zipfile.ZIP_DEFLATED) as z:
  z.write(ROOT/'index.html','index.html')
  z.write(d/'assets'/'Inter-LICENSE.txt','Inter-LICENSE.txt')
 print('Dashboard autónomo, informe y paquete web generados')
if __name__=='__main__':main()
